import java.util.*;

class Solution {
    public boolean isMirror(int n) {
        if (n < 0) return false;             // minus sign can't mirror
        long x = n, rev = 0;                 // long: reversed value may exceed int
        while (x > 0) {
            rev = rev * 10 + x % 10;         // append last digit of x to rev
            x /= 10;
        }
        return rev == n;
    }
}

